-- Cardápio importado do site antigo (cozinhadocedoce.wixsite.com/cozinhadoce/teste).
-- Cole no SQL Editor do Supabase e clique em Run. Pode rodar de novo: apaga só os doces importados antes.

-- Aparência: chocolate, como o site antigo
update public.app_settings set primary_color = '#7b4a2e', tagline = 'Macarons e doces finos · Milena Andrade', updated_at = now() where id = 1;

-- Categorias do cardápio (as de exemplo que não têm doce saem)
insert into public.categories (slug, name, emoji, position) values
  ('macarons', 'Macarons', '🌸', 1),
  ('macarons_decorados', 'Macarons decorados', '🦄', 2),
  ('macarons_pintados', 'Macarons pintados', '✨', 3),
  ('mini_macarons', 'Mini macarons', '🍬', 4),
  ('macarons_palito', 'Macarons no palito', '🍭', 5),
  ('caixinhas', 'Caixinhas', '🎁', 6),
  ('brownies', 'Brownies', '🍫', 7),
  ('madeleines', 'Mini madeleines', '🧈', 8),
  ('suspiros', 'Suspiros', '☁️', 9),
  ('cheesecakes', 'Cheesecakes', '🍰', 10)
on conflict (slug) do update set name = excluded.name, emoji = excluded.emoji, position = excluded.position;
delete from public.categories c
where c.slug not in ('macarons','macarons_decorados','macarons_pintados','mini_macarons','macarons_palito','caixinhas','brownies','madeleines','suspiros','cheesecakes')
  and not exists (select 1 from public.products p where p.category = c.slug);

